+
+test("concurrent additions get distinct ids and retain every item", async () => {
+  const before = await fetchItems();
+  const nextId = Math.max(0, ...before.map((item) => item.id)) + 1;
+  const added = await Promise.all(
+    ["oats", "beans", "lentils"].map((name) => addItem({ name, qty: 1 })),
+  );
+
+  assert.deepEqual(added.map((item) => item.id), [nextId, nextId + 1, nextId + 2]);
+  const after = await fetchItems();
+  assert.equal(after.length, before.length + added.length);
+  for (const item of added) {
+    assert.deepEqual(after.find((stored) => stored.id === item.id), item);
+  }
+});
